    "Name": "B2BAdminTools",
    "Key": "B2B",
    "ResourceKey": "B2B",
    "Script": "B2BAdminTools = {
    init: async function (app, container) {
        app = app || session.app;
        container = container || $(".component[name=B2BAdminTools]");
        api.addToMetaCache([
            {
                "Name": "B2B",
                "Types": [
                    [meta[B2B/System]],
                    [meta[B2B/Company]],
                    [meta[B2B/Currency]]
                ]
            }
        ]);
        $("[name=addCompany]", container).off("click").on("click", async (e) => await B2BAdminTools.newCompany(e, app));
        $("[name=clearCompanies]", container).off("click").on("click", async (e) => await B2BAdminTools.clearCompanies(e, app));

        $("[name=addInvoice]", container).on("click", async (e) => await B2BAdminTools.newInvoice(e, app));
        $("[name=addCredit]", container).on("click", async (e) => await B2BAdminTools.newCredit(e, app));
        $("[name=addPayment]", container).on("click", async (e) => await B2BAdminTools.newPayment(e, app));
        $("[name=addPurchaseOrder]", container).on("click", async (e) => await B2BAdminTools.newPurchaseOrder(e, app));
        $("[name=clearTransactions]", container).on("click", async (e) => await B2BAdminTools.clearTransactions(e, app));
        $("[name=importTransactionsFromData]", container).on("click", async (e) => await B2BAdminTools.importTransactionData(e,app));
        $("[name=updateTransactions]", container).on("click", async (e) => await B2BAdminTools.updateTransactionLine(e,app));
        $("[name=importTransactions]", container).on("click", async (e) => await B2BAdminTools.runTransactionsImport(e,app));
        $("[name=migrateFunderData]", container).on("click", async (e) => await B2BAdminTools.migrateFunderData(e,app));

        $("[name=importCompaniesFromData]", container).on("click", async (e) => await B2BAdminTools.importCompanyData(e, app));
        $("[name=importCompanies]", container).on("click", async (e)  => await B2BAdminTools.runMasterdataImport(e,app));

        var folder = await api.get("DocumentManagement/Folder?$filter=Path eq 'data' and AppId eq " + app.Id);
        if(folder.value.length === 0) {
            $("[name=createDMSStructure]", container).on("click", async (e) => await B2BAdminTools.createDMSStructure(e));
        } else {
            $("[name=dmsComponent]", container).hide();
        }

        var task = await api.get("Workflow/ScheduledTask?$filter=AppId eq " + app.Id + "and contains(Name, 'offer')")
        if(task.value.length > 0 ){
            $("[name=generateOffers]", container).on("click", async (e) => await B2BAdminTools.generateOffers(e,app));
        } else {
            $("[name=fundingComponent]", container).hide();
        }

        $("[name=createBuyerAdminAccount]", container).on("click", (e) => B2BAdminTools.createBuyerAdminAccount(e, app));
    },

    createBuyerAdminAccount: async function(e, app) {
        e.preventDefault();
        var d = new Dialog({title: "[resource_displayname[register]]", width: 800, height: 600});
        d.init(async () => {
            await loadComponent($(d.element), "Register", (c) => {
                c.init(app, $(".component[name=Register]", d.element), d, async (ssoUser) => {
                    var userId = ssoUser.id;
                    var appInfo = await api.get("ContentManagement/App(" + app.Id + ")?$select=ConfigJson");
                    /* b2b onboarding */
                    var config = JSON.parse(appInfo.ConfigJson);
                    var rootBucketId = config.B2B.RootBucket;
                    var buyerAdminRoleId = (await api.get("B2B/BucketRole?$filter=BucketId eq " + rootBucketId + " and (contains(Role/Name, 'Buyer') or contains(Role/Name, 'Debtor'))")).value[0].RoleId;
                    await api.post("B2B/B2BUserRole", { UserId: userId, RoleId: buyerAdminRoleId  }).catch((err) => error(err));
                    /* core onboarding */
                    var coreBuyerRoleId = (await api.get("AppSecurity/Role?$filter=contains(Name, 'Buyer') and AppId eq " + app.Id)).value[0].Id;
                    await api.post("AppSecurity/UserRole", { UserId: userId, RoleId: coreBuyerRoleId }).catch((err) => error(err));

                    var coreAdminRoleId = (await api.get("AppSecurity/Role?$filter=contains(Name, 'Admin') and AppId eq " + app.Id)).value[0].Id;
                    await api.post("AppSecurity/UserRole", { UserId: userId, RoleId: coreAdminRoleId }).catch((err) => error(err));
                    await B2BAdminTools.createDMSStructure(e);
                    var masterdataFlow = (await api.get("Workflow/FlowDefinition?$filter=AppId eq " + app.Id + " and contains(Process/Name, 'Masterdata') and contains(Name, 'Import')")).value[0].Id;
                    var transactionsFlow = (await api.get("Workflow/FlowDefinition?$filter=AppId eq " + app.Id + " and contains(Process/Name, 'Transactions') and contains(Name, 'Import')")).value[0].Id;
                    await api.post("Workflow/WorkflowEvent",
                        {
                            "Type":"DocumentManagement/File",
                            "EventContext":"App(" + app.Id + ")/DMS(File_Created)/data/transactions/received",
                            "FlowId":transactionsFlow,
                            "ExecuteAs":userId
                        });
                    await api.post("Workflow/WorkflowEvent",
                        {
                            "Type":"DocumentManagement/File",
                            "EventContext":"App(" + app.Id + ")/DMS(File_Created)/data/masterdata/received",
                            "FlowId":masterdataFlow,
                            "ExecuteAs":userId
                        });
                    notification.success("[resource_displayname[adminusercreated]]");
                });
            });
        })
    },


    createDMSStructure: async function(e) {
        e.preventDefault();
        await api.post("DMS/data/transactions/received", null);
        await api.post("DMS/data/transactions/transformed", null);
        await api.post("DMS/data/transactions/processed", null);
        await api.post("DMS/data/masterdata/received", null);
        await api.post("DMS/data/masterdata/transformed", null);
        await api.post("DMS/data/masterdata/processed", null);
        notification.success("[resource_displayname[built]]");
    },


    clearTransactions: async function(e, app) {
        e.preventDefault();
        var sourceSystem = app.Config.B2B.SourceSystem;
        var d = new ConfirmDialog({
            title: "[resource_displayname[areyousure]]",
            question: "[resource_displayname[areyousure]]",
            close: "[resource_displayname[close]]",
            confirm: "[resource_displayname[confirm]]"
        });
        d.events.confirm = async function () {
            var consoleDialog = new ConsoleDialog();
            consoleDialog.title = "[resource_displayname[cleardowntransactions]]";
            consoleDialog.init();

            await api.destroy("B2B/Transactions/ClearDown?sourceSystemId=" + sourceSystem).catch((e) => {
                consoleDialog.log("error", JSON.stringify(e));
                error(e);
            });
            consoleDialog.log("success", "[resource_displayname[cleared]]");
            consoleDialog.events.close();
        };
        d.init();
    },

    clearCompanies: async function(e, app) {
        e.preventDefault();
        var sourceSystems = app.Config.B2B.SourceSystem;
        var rootBucket = app.Config.B2B.RootBucket;

        var consoleDialog = new ConsoleDialog();
        consoleDialog.title = "[resource_displayname[clearcompanies]]";
        consoleDialog.init();
        await B2BAdminTools.batchDelete("B2B/Company", consoleDialog, sourceSystems);
        var rootBucket = await api.get("B2B/Bucket(" + rootBucket + ")?$expand=Buckets");
        var childBucketIds = rootBucket.Buckets.map(i => i.Id);
        consoleDialog.log("info", "[resource_displayname[retrievingbuckets]]");
        var buckets = await api.get("B2B/Bucket?$filter=ParentId in (" + childBucketIds.join() + ")&$select=Id");

        consoleDialog.log("info", "[resource_displayname[deletingbuckets]]");
        await api.post("B2B/Bucket/DeleteAll", { value: buckets.value.map(b => b.Id) });

        consoleDialog.log("success", "[resource_displayname[cleared]]");
        consoleDialog.events.close();
    },

    batchDelete: async function(endpoint, consoleDialog, sourceSystems) {
        consoleDialog.log("info", "[resource_displayname[clearing]] " + endpoint);
        var transactions = await api.get(endpoint + "/FromSystem(SystemId='" + sourceSystems + "')?$select=Id&$top=1000").catch((e) => {
            consoleDialog.log("error", JSON.stringify(e));
            error(e);
        });
        while(transactions.value.length === 1000) {
            consoleDialog.log("info", "[resource_displayname[retrievingbatchof]] " + endpoint);
            await api.post(endpoint + "/DeleteAll", { value: transactions.value.map(o => o.Id) }).catch((e) => {
                consoleDialog.log("error", JSON.stringify(e));
                error(e);
            });
            transactions = await api.get(endpoint + "/FromSystem(SystemId='" + sourceSystems + "')?$select=Id&$top=1000").catch((e) => {
                consoleDialog.log("error", JSON.stringify(e));
                error(e);
            });
        }
        await api.post(endpoint + "/DeleteAll", { value: transactions.value.map(o => o.Id) }).catch((e) => {
            consoleDialog.log("error", JSON.stringify(e));
            error(e);
        });
        consoleDialog.log("info", "[resource_displayname[cleared]] " + endpoint);
    },

    newCompany: async function (e, app) {
        e.preventDefault();
        var validator = null;
        var rootBucket = await api.get("B2B/Bucket(" + app.Config.B2B.RootBucket + ")?$expand=Buckets");
        var newCompanyDialog = new Dialog({ width: 1320, height: "auto", title: "[resource_displayname[newcompany]]" })
        newCompanyDialog.template = $("[name=newCompanyDialog]").html();
        var referencesGrid = null;
        newCompanyDialog.events.create = async function (e) {
            e.preventDefault();
            var buyerChecked = ($("[name=buyer]", newCompanyDialog.element).is(":checked"));
            var supplierChecked = ($("[name=supplier]", newCompanyDialog.element).is(":checked"));
            var funderChecked = ($("[name=funder]", newCompanyDialog.element).is(":checked"));
            if (!validator.validate()) {
                return;
            }
            if (!(buyerChecked || supplierChecked || funderChecked)) {
                return;
            }
            var newCompany = {
                Name: $("[name=name]", newCompanyDialog.element).val(),
                CreatedOn: (new Date()).toISOString(),
                LastUpdated: (new Date()).toISOString(),
                CreatedBy: session.user,
                LastUpdatedBy: session.user,
                DateTradingEnabled: (new Date()).toISOString(),
                IsActive: true,
                Address: {
                    Line1: $("[name=AddressLine1]", newCompanyDialog.element).val(),
                    Line2: $("[name=AddressLine2]", newCompanyDialog.element).val(),
                    StateOrProvince: $("[name=StateOrProvince]", newCompanyDialog.element).val(),
                    TownOrCity: $("[name=TownOrCity]", newCompanyDialog.element).val(),
                    ZipOrPostalCode: $("[name=ZipOrPostalCode]", newCompanyDialog.element).val(),
                    CountryId: $("[name=CountryId]", newCompanyDialog.element).val()
                },
                References: referencesGrid.dataSource().data().toJSON()
            };
            await api.add("B2B/Company", newCompany).then(async () => {
                notification.success("[resource_displayname[added]]");
                if (buyerChecked) {
                    var buyerBucket = rootBucket.Buckets.filter(r => r.Key == "DebtorGroup")[0];
                    await api.post("B2B/Bucket(" + buyerBucket.Id + ")/ImportBuyers", { value: newCompany.References.map(r => r.SystemId + "|" + r.Value) }).then(() => notification.success("[resource_displayname[buyerimported]]"))
                        .catch((err) => error(err));
                }
                if (supplierChecked) {
                    var supplierBucket = rootBucket.Buckets.filter(r => r.Key == "CreditorGroup")[0];
                    await api.post("B2B/Bucket(" + supplierBucket.Id + ")/ImportSuppliers", { value: newCompany.References.map(r => r.SystemId + "|" + r.Value) }).then(() => notification.success("[resource_displayname[supplierimported]]"))
                        .catch((err) => error(err));
                }
                if (funderChecked) {
                    var funderBucket = rootBucket.Buckets.filter(r => r.Key == "FunderGroup")[0];
                    await api.post("B2B/Bucket(" + funderBucket.Id + ")/ImportFunders", { value: newCompany.References.map(r => r.SystemId + "|" + r.Value) }).then(() => notification.success("[resource_displayname[funderimported]]"))
                        .catch((err) => error(err));
                }
            }).catch((err)=>error(err));
            newCompanyDialog.events.close();
        };
        newCompanyDialog.init(()=>{
            validator = $(newCompanyDialog.element).kendoValidator().data("kendoValidator");
        });
        var countries = await api.get("B2B/Country");
        $("input[name=CountryId]", newCompanyDialog.element).kendoDropDownList({
            dataSource: { data: countries.value, sort: [{ field: "Name", dir: "asc" }] },
            dataValueField: "Id",
            dataTextField: "Name"
        });

        var references = app.Config.B2B.References?.Systems || [];
        references = references.map((r) => { return { SystemId: r, Value: null }; });

        referencesGrid = new GridWidget($("[name=referencesGrid]", newCompanyDialog.element), { data: references });
        var systemIds = (await api.get("B2B/System?$select=Id")).value.map(r => ({value:r.Id, text:r.Id}));
        referencesGrid.columns = [
            { field: "SystemId", title: "[resource_displayname[systemid]]", values: systemIds},
            { field: "Value", title: "[resource_displayname[value]]" }
        ];
        referencesGrid.commands.push({ name: "remove", icon: "k-i-delete", text: "[resource_displayname[remove]]" });
        referencesGrid.dataBound = function (e) {
            $("[name=remove]", referencesGrid.gridElement).off("click").on("click", (e) => B2BAdminTools.removeReference(e, referencesGrid));
        };
        // referencesGrid.toolbar = "<button name='add'><span class='k-icon k-i-plus'></span>[resource_displayname[add]]</button>";
        referencesGrid.groupable = false;
        referencesGrid.filterable = false;
        referencesGrid.pageable = false;
        referencesGrid.scrollable = false;

        await referencesGrid.init();
        $("[name=add]", referencesGrid.gridElement).off("click").on("click", (e) => B2BAdminTools.newReference(e, referencesGrid));
    },

    newReference: async function (e, referencesGrid) {
        e.preventDefault();
        referencesGrid.dataSource().add({SystemId: "", Value: ""});
    },

    removeReference: async function (e, referencesGrid) {
        e.preventDefault();
        var item = referencesGrid.dataItem($(e.currentTarget).closest("tr"));
        referencesGrid.dataSource().remove(item);
    },

