            onChange: function (e) {
                company.References = this.data();
                for (var i in company.References) {
                    company.References[i].Id = company.References[i].SystemId + "|" + company.References[i].Value;
                    delete company.References[i].type;
                }
            }
        };
        var ds = await model.getDatasource(config);

        var systems = await model.getDatasource({ endpoint: "B2B/System" });
        var referenceGrid = new GridWidget(container, ds);
        referenceGrid.toolbar = "<button name='create'><span class='k-icon k-i-plus'></span>[resource_displayname[newreference]]</button>";
        referenceGrid.groupable = false;
        referenceGrid.editable = false;
        referenceGrid.pageable = false;
        referenceGrid.columns =
        [
            {
                field: "SystemId",
