                editor: function (cell, options) {
                    $('<input data-text-field="Name" data-value-field="Id" data-bind="value:' + options.field + '"/>')
                        .appendTo(cell)
                        .kendoDropDownList({ dataSource: systems, dataTextField: "Name", dataValueField: "Id" });
