        referenceGrid.commands.push({ name: "delete", icon: "k-i-delete", text: "[resource_displayname[delete]]" });
        referenceGrid.dataBound = function () {
            $("a[name=delete]", referenceGrid.gridElement).on("click", (e) => CompanyReferenceManagement.destroy(e, referenceGrid));
        };
        await referenceGrid.init();
        $("button[name=create]", referenceGrid.gridElement).off().on("click", (e) => CompanyReferenceManagement.create(company, referenceGrid));
    },

    create: async function(company, grid, systems) {
