    "Script": "DebtorStatePieChart = {
    init: async function (app, container) {
        app = app || session.app;
        container = container || $(".component[name=DebtorStatePieChart]");

        var defaultCurrency = app.Config.B2B.DefaultCurrency ? app.Config.B2B.DefaultCurrency : "EUR";
        var data = await DebtorStatePieChart.getData(app, defaultCurrency);
        var chartContainer = $("[name=chart]", container);
        var chart = new PieChart(chartContainer, data);

        chartContainer.data('component', {
            chart: chart
        });

        $("[name=currencyDropdown]", container).kendoDropDownList({
            dataSource: app.Config.B2B.Currencies ? app.Config.B2B.Currencies : ["USD", "EUR", "GBP"],
            change: async function (e) {
                var value = this.value();
                chart.setData(await DebtorStatePieChart.getData(app, value));
                chart.refresh();
            }
        }).data("kendoDropDownList");

        chart.init();
        $("svg", container).css("overflow", "visible");
        $("[name=currencyDropdown]", container).data("kendoDropDownList").value(defaultCurrency);
    },

    getData: async function (app, currency) {
        var activeTransactions = await api.get(`B2B/ActiveTransaction/FromSystem(SystemId='${app.Config.B2B.SourceSystem}')?$apply=filter(CurrencyId eq '${currency}')/groupby((DebtorState), aggregate(Value with sum as Sum))`);
        activeTransactions = activeTransactions.sort((a,b) => a.Sum < b.Sum ? 1 : -1);
        var data = [];
        var colors = app.Config.Themes.Default.colours.charts;
        for (var i = 0; i < activeTransactions.length; i = i + 1) {
            data.push({
                category: B2B.transactionStates[activeTransactions[i].DebtorState],
                value: activeTransactions[i].Sum,
                color: colors[i],
            });
        }

        return data;
    }
}",
