    "Name": "OutstandingBalanceByDueDate",
    "Key": "B2B",
    "ResourceKey": "B2B",
    "Script": "OutstandingBalanceByDueDate = {
    init: async function (app, container) {
        app = app || session.app;
        container = container || $(".component[name=OutstandingBalanceByDueDate]");

        const firstDay = (new Date()).toISOString().split("T")[0];
        var lastDay = new Date();
        lastDay.setDate(lastDay.getDate() + 75);
        lastDay = lastDay.toISOString().split("T")[0];
        var defaultCurrency = app.Config.B2B.DefaultCurrency
            ? app.Config.B2B.DefaultCurrency
            : "EUR";

        $("[name=outstandingHeader]", container).html($("[name=outstandingHeader]", container).html() + " " + kendo.toString(new Date(firstDay), type.dateFormat) + " - " + kendo.toString(new Date(lastDay), type.dateFormat));
        var data = await OutstandingBalanceByDueDate.getData(app, firstDay, lastDay);

        var chartContainer = $("[name=chart]", container);
        OutstandingBalanceByDueDate.initChart(chartContainer, data, defaultCurrency);

        $("[name=currencyDropdown]", container)
            .kendoDropDownList({
                dataSource: app.Config.B2B.Currencies
                    ? app.Config.B2B.Currencies
                    : ["USD", "EUR", "GBP"],
                change: async function (e) {
                    var value = this.value();
                    var data = await OutstandingBalanceByDueDate.getData(app, firstDay, lastDay);
                    OutstandingBalanceByDueDate.initChart(chartContainer, data, value);
                }
            })
            .data("kendoDropDownList");

        $("[name=currencyDropdown]", container)
            .data("kendoDropDownList")
            .value(defaultCurrency);
    },

    getData: async function (app, firstDay, lastDay) {
        var chartData =  await api.get(`B2B/ActiveTransaction/FromSystem(SystemId='${app.Config.B2B.SourceSystem}')?$apply=filter(DebtorPaymentDate ge ${firstDay} and DebtorPaymentDate le ${lastDay})/groupby((DebtorPaymentDate,CurrencyId), aggregate(Value with sum as UnpaidValue))`);
        return chartData.sort((a, b) => b.DebtorPaymentDate - a.DebtorPaymentDate);        
    },

    getFilteredData: function(data, currency) {
        return data.filter(d => d.CurrencyId == currency);
    },

    getFormattedData: function(data, currency, dates) {
        var filteredData = OutstandingBalanceByDueDate.getFilteredData(data, currency);
        return dates.map(d => filteredData.filter(i => i.DebtorPaymentDate == d)).flat();
    },

    initChart: function (chartContainer, data, currency) {
        var categories = data.map(i => i.DebtorPaymentDate);

        var args = {
            showLegend: true,
            valueTemplate: "#: kendo.toString(value, type.aggregateMoneyFormat)#",
            tooltipTemplate: "#= series.name #: #= kendo.toString(value, type.aggregateMoneyFormat) #",
            categoryTemplate: "#= kendo.toString(new Date(value), type.dateFormat) #",
            series: [{
                field: "UnpaidValue",
                categoryField: "DebtorPaymentDate",
                name: "[resource_displayname[UnpaidValue]] (" + currency + ")",
                data: this.getFormattedData(data, currency, categories)
            }],
            categories: categories,
            max: data.filter(d => d.CurrencyId == currency).map(i => i.UnpaidValue).sort((a, b) => b - a)[0],
            type: "column"
        };

        var chart = new Chart(chartContainer, args);
        chartContainer.data('component', {
            chart: chart
        });

        chart.init();
    }
}",
