    "Script": "api.addToMetaCache([
    {
        Name: "AppSecurity",
        Types: [
            [meta[AppSecurity/User]]
        ]
    },
    {
        Name: "ContentManagement",
        Types: [
            [meta[ContentManagement/Submission]]
        ]
    }
]);
RegistrationOfInterest = {
	states: {
		"New": "[resource_displayname[New]]",
		"Rejected": "[resource_displayname[rejected]]",
		"AdminRejected": "[resource_displayname[adminRejected]]",
		"Accepted": "[resource_displayname[accepted]]"
	},

	init: async function (app, container) {
		var meta = [
			{
				"Name": "Core",
				"Types": [
					[meta[ContentManagement/Submission]]
				]
			}
		];
		var config = { endpoint: "ContentManagement/Submission", odataAppend: "?$filter=SourceComponent eq 'RegistrationOfInterest'  and CreatedBy eq '" + session.user + "' and AppId eq " + app.Id };
		var ds = await model.getDatasource(config);
		var roiGrid = await [script[RoiGrid]]({element: $("[name=roiGrid]", container), data: ds});
		await roiGrid.init();
		$("[name=addROI]").on("click", function (e) { e.preventDefault(); RegistrationOfInterest.createROI(container, roiGrid, app); });
	},

	createROI: async function (container, widget, app) {
		var d = new Dialog({ title: "[resource_displayname[newAccessRequest]]", width: 1000 });
		var user = await api.get("AppSecurity/User/Me()");
		var model = kendo.observable({
			0: {firstname: user.DisplayName. split(' ')[0], lastname:user.DisplayName.split(' ')[user.DisplayName.split(' ').length - 1], email: user.Email, phone: null, jobtitle: null},
			1: {company: null, requestType: null, reference: null, contactName: null, contactEmail: null, contactPhone: null},
			2: {signatoryName: null, signatoryPosition: null, signarotyPhone: null, bankName: null, accountNo: null, sortCode: null},
			3: {signature: null, ident1: null, ident2: null, accounts: null, shareholderDetails: null, associationDetails: null, contract: null}
		});
		d.template = "<div name='newFundingRequestDialog'>" + $("script[name=createRequest]", container).html() + "</div>";
		d.events.save = async function (e) {
			var items = JSON.parse(JSON.stringify(model));
			var submission = { SourceComponent: "RegistrationOfInterest", State: "New", DataJson: JSON.stringify({ "fields": items }), AppId: app.Id };
			await api.add("ContentManagement/Submission", submission);
			notification.success("[resource_displayname[SubmissionSubmitted]]");
			widget.kendoObject.dataSource.read();
			widget.kendoObject.refresh();
			d.events.close();
		};
		d.init(async () => {
			var dialog = d.element;
			await api.get("B2B/Country").then((countries) => {
				$("input[name=country]", dialog).kendoDropDownList({
					dataSource: countries.value,
					dataValueField: "Id",
					dataTextField: "Name"
				});
			});
			$("select", dialog).kendoDropDownList();
			kendo.bind(dialog, model);
			$(".partsList > ul > li", dialog).on("click", function(e) {
				$(".partsList > ul > li", dialog).removeClass("selected");
				$(".container", dialog).css("display", "none");
				$(".container[name=" + $(e.target).attr("data-container") + "]").css("display", "inline-block");
				$(e.target).addClass("selected");
			});
		});
	}
};",
