    "Script": "SystemsManagement = {
	init: async function (app, container) {
		app = app || session.app;
		container = container || $(".component[name=SystemsManagement]");
		await SystemsManagement.setup(container);
	},

	setup: async function (container) {
		var ds = await model.getDatasource({ endpoint: "B2B/System" });
		var grid = new GridWidget(container, ds);
		grid.groupable = false;
		grid.toolbar =  "<button name='create'><span class='k-icon k-i-plus'></span>[resource_displayname[NewSystem]]</button>";
		grid.columns = [
			{ field: "Id", title: "[resource_shortdisplayname[Id]]", width: 200 },
			{ field: "Name", title: "[resource_shortdisplayname[Name]]", width: 300 },
			{ field: "Description", title: "[resource_shortdisplayname[Description]]" },
			{ width: 100, template: "<a name='destroy'><span class='k-icon k-i-delete'></span>[resource_displayname[Delete]]</a>" }
		];
		grid.dataBound = function() {
			$("a[name=destroy]", grid.gridElement).on("click", (e) => SystemsManagement.destroy(e, container));
		};
		await grid.init();
		$("button[name=create]", grid.gridElement).on("click", (e) => SystemsManagement.newSystem(e, grid));
	},

	newSystem: function (e, grid) {
		var newSystemEditor = {
			Id: "",
			Name: "",
			Description: "",
			BucketId: ""
		};

		var args = {
			fields: [
				{ field: "Id", title: "[resource_displayname[id]]" }, 
				{ field: "Name", title: "[resource_displayname[name]]" },
				{ field: "Description", title: "[resource_displayname[description]]" },
				{ field: "BucketId", title: "[resource_displayname[bucketid]]" }
			],
			title: "[resource_displayname[newsystem]]",
			resourceKey: "B2B",
			data: newSystemEditor
		};
			var addSystemDialog = new EditorDialog(args);
			addSystemDialog.events.confirm = async function () {
				newSystemEditor = addSystemDialog.data.toJSON();//Remove all the kendo observable properties.
				newSystem = {
					Id: newSystemEditor.Id,
					Name: newSystemEditor.Name,
					Description: newSystemEditor.Description,
					Buckets: [
						{ BucketId: newSystemEditor.BucketId, SystemId: newSystemEditor.Id }
					]
				};
				await api.add("B2B/System", newSystem).then(() => {
					addSystemDialog.events.close();
					notification.success('[resource_description[SystemCreated]]');
					grid.refresh();
				}).catch((e) => error(e));
			}
			addSystemDialog.init();
	},

	save: function (e, container) {
		e.preventDefault();
		var grid = $("[name=grid]", container).data("kendoGrid");
		var system = grid.dataItem($(e.currentTarget).closest("tr"));
		system.save(e, function () { notification.success("[resource_description[SystemSaved]]"); });
	},

	destroy: function (e, grid) {
		e.preventDefault();
		var d = new ConfirmDialog({title: "[resource_displayname[areyousure]]", question: "[resource_displayname[areyousure]]", yes: "[resource_displayname[yes]]", no: "[resource_displayname[no]]"});
		d.events.confirm = async function() {
			var system = grid.kendoObject.dataItem($(e.currentTarget).closest("tr"));
			system.destroy(e, function () {
				notification.success("[resource_description[SystemDeleted]]");
				grid.refresh();
			});
		};
		d.init();
	}
}

